import json
import sys

def main(api_url: str, filter_status: str):
    """Fetch and filter API data."""
    # Simulated API response processing
    mock_data = [
        {"id": 1, "status": "active", "name": "Resource A"},
        {"id": 2, "status": "inactive", "name": "Resource B"},
        {"id": 3, "status": "active", "name": "Resource C"}
    ]

    filtered = [item for item in mock_data if item["status"] == filter_status]

    return {
        "total_count": len(mock_data),
        "filtered_count": len(filtered),
        "results": filtered
    }

if __name__ == "__main__":
    result = main(api_url="https://api.example.com/resources", filter_status="active")
    print(json.dumps(result))
